import { z } from "zod";
var ProviderModelIdSchema = z.string().regex(/^[^/\s]+\/[^\s]+$/, "Expected provider/model format (provider/.../model)");
var ManualAgentPlanSchema = z.object({
  primary: ProviderModelIdSchema,
  fallback1: ProviderModelIdSchema,
  fallback2: ProviderModelIdSchema,
  fallback3: ProviderModelIdSchema
}).superRefine((value, ctx) => {
  const unique = new Set([
    value.primary,
    value.fallback1,
    value.fallback2,
    value.fallback3
  ]);
  if (unique.size !== 4) {
    ctx.addIssue({
      code: z.ZodIssueCode.custom,
      message: "primary and fallbacks must be unique per agent"
    });
  }
});
var ManualPlanSchema = z.object({
  orchestrator: ManualAgentPlanSchema,
  oracle: ManualAgentPlanSchema,
  designer: ManualAgentPlanSchema,
  explorer: ManualAgentPlanSchema,
  librarian: ManualAgentPlanSchema,
  fixer: ManualAgentPlanSchema
}).strict();
var AgentModelChainSchema = z.array(z.string()).min(1);
var FallbackChainsSchema = z.object({
  orchestrator: AgentModelChainSchema.optional(),
  oracle: AgentModelChainSchema.optional(),
  designer: AgentModelChainSchema.optional(),
  explorer: AgentModelChainSchema.optional(),
  librarian: AgentModelChainSchema.optional(),
  fixer: AgentModelChainSchema.optional(),
  steward: AgentModelChainSchema.optional(),
  interpreter: AgentModelChainSchema.optional()
}).catchall(AgentModelChainSchema);
var SkillOrMcpConfigSchema = z.union([
  z.array(z.string()),
  z.object({
    "always-load": z.array(z.string()).optional(),
    mandatory: z.array(z.string()).optional(),
    wildcard: z.boolean().optional()
  })
]);
var AgentOverrideConfigSchema = z.object({
  model: z.union([
    z.string(),
    z.array(z.union([
      z.string(),
      z.object({
        id: z.string(),
        variant: z.string().optional()
      })
    ])).min(1)
  ]).optional(),
  temperature: z.number().min(0).max(2).optional(),
  variant: z.string().optional().catch(undefined),
  options: z.record(z.string(), z.unknown()).optional(),
  displayName: z.string().min(1).optional(),
  skills: SkillOrMcpConfigSchema.optional(),
  mcps: SkillOrMcpConfigSchema.optional()
}).strict();
var PresetSchema = z.record(z.string(), AgentOverrideConfigSchema);
var WebsearchConfigSchema = z.object({
  provider: z.enum(["exa", "tavily"]).default("exa")
});
var McpNameSchema = z.enum(["websearch", "context7", "grep_app"]);
var SessionManagerConfigSchema = z.object({
  maxSessionsPerAgent: z.number().int().min(1).max(10).default(2),
  readContextMinLines: z.number().int().min(0).max(1000).default(10),
  readContextMaxFiles: z.number().int().min(0).max(50).default(8)
});
var TodoContinuationConfigSchema = z.object({
  maxContinuations: z.number().int().min(1).max(50).default(5).describe("Maximum consecutive auto-continuations before stopping to ask user"),
  cooldownMs: z.number().int().min(0).max(30000).default(3000).describe("Delay in ms before auto-continuing (gives user time to abort)"),
  autoEnable: z.boolean().default(false).describe("Automatically enable auto-continue when the orchestrator session has enough todos"),
  autoEnableThreshold: z.number().int().min(1).max(50).default(4).describe("Number of todos that triggers auto-enable (only used when autoEnable is true)")
});
var ContextPressureConfigSchema = z.object({
  enabled: z.boolean().default(true).describe("When true, warn the orchestrator on high context usage before the model fails."),
  warnThresholdPct: z.number().min(1).max(99).default(75).describe("Inject a /compact reminder when context (used ÷ limit) is at least this percent.")
});
var FailoverConfigSchema = z.object({
  enabled: z.boolean().default(true),
  timeoutMs: z.number().min(0).default(15000),
  retryDelayMs: z.number().min(0).default(500),
  chains: FallbackChainsSchema.default({}),
  retry_on_empty: z.boolean().default(true).describe("When true (default), empty provider responses are treated as failures, " + "triggering fallback/retry. Set to false to treat them as successes.")
});
var PluginConfigSchema = z.object({
  preset: z.string().optional(),
  setDefaultAgent: z.boolean().optional(),
  scoringEngineVersion: z.enum(["v1", "v2-shadow", "v2"]).optional(),
  balanceProviderUsage: z.boolean().optional(),
  autoUpdate: z.boolean().optional().describe("Disable automatic installation of plugin updates when false. Defaults to true."),
  manualPlan: ManualPlanSchema.optional(),
  presets: z.record(z.string(), PresetSchema).optional(),
  agents: z.record(z.string(), AgentOverrideConfigSchema).optional(),
  websearch: WebsearchConfigSchema.optional(),
  sessionManager: SessionManagerConfigSchema.optional(),
  todoContinuation: TodoContinuationConfigSchema.optional(),
  contextPressure: ContextPressureConfigSchema.optional(),
  fallback: FailoverConfigSchema.optional()
});

// src/config/loader.ts
var PROMPTS_DIR_NAME = "opencode-dux";
function loadConfigFromPath(configPath) {
  try {
    const content = fs.readFileSync(configPath, "utf-8");
    const rawConfig = JSON.parse(stripJsonComments(content));
    const result = PluginConfigSchema.safeParse(rawConfig);
    if (!result.success) {
      console.warn(`[opencode-dux] Invalid config at ${configPath}:`);
      console.warn(result.error.format());
      return null;
    }
    return result.data;
  } catch (error) {
    if (error instanceof Error && "code" in error && error.code !== "ENOENT") {
      console.warn(`[opencode-dux] Error reading config from ${configPath}:`, error.message);
    }
    return null;
  }
}
function findConfigPath(basePath) {
  const jsoncPath = `${basePath}.jsonc`;
  const jsonPath = `${basePath}.json`;
  if (fs.existsSync(jsoncPath)) {
    return jsoncPath;
  }
  if (fs.existsSync(jsonPath)) {
    return jsonPath;
  }
  return null;
}
function findConfigPathInDirs(configDirs, baseName) {
  for (const configDir of configDirs) {
    const configPath = findConfigPath(path.join(configDir, baseName));
    if (configPath) {
      return configPath;
    }
  }
  return null;
}
function deepMerge(base, override) {
  if (!base)
    return override;
  if (!override)
    return base;
  const result = { ...base };
  for (const key of Object.keys(override)) {
    const baseVal = base[key];
    const overrideVal = override[key];
    if (typeof baseVal === "object" && baseVal !== null && typeof overrideVal === "object" && overrideVal !== null && !Array.isArray(baseVal) && !Array.isArray(overrideVal)) {
      result[key] = deepMerge(baseVal, overrideVal);
    } else {
      result[key] = overrideVal;
    }
  }
  return result;
}
function loadPluginConfig(directory) {
  const userConfigPath = findConfigPathInDirs(getConfigSearchDirs(), "opencode-dux");
  const projectConfigBasePath = path.join(directory, ".opencode", "opencode-dux");
  const projectConfigPath = findConfigPath(projectConfigBasePath);
  let config = userConfigPath ? loadConfigFromPath(userConfigPath) ?? {} : {};
  const projectConfig = projectConfigPath ? loadConfigFromPath(projectConfigPath) : null;
  if (projectConfig) {
    config = {
      ...config,
      ...projectConfig,
      agents: deepMerge(config.agents, projectConfig.agents),
      sessionManager: deepMerge(config.sessionManager, projectConfig.sessionManager),
      contextPressure: deepMerge(config.contextPressure, projectConfig.contextPressure),
      fallback: deepMerge(config.fallback, projectConfig.fallback)
    };
  }
  const envPreset = process.env.OH_MY_OPENCODE_SLIM_PRESET;
  if (envPreset) {
    config.preset = envPreset;
  }
  if (config.preset) {
    const preset = config.presets?.[config.preset];
    if (preset) {
      config.agents = deepMerge(preset, config.agents);
    } else {
      const presetSource = envPreset === config.preset ? "environment variable" : "config file";
      const availablePresets = config.presets ? Object.keys(config.presets).join(", ") : "none";
      console.warn(`[opencode-dux] Preset "${config.preset}" not found (from ${presetSource}). Available presets: ${availablePresets}`);
    }
  }
  return config;
}
function loadAgentPrompt(agentName, preset) {
  const presetDirName = preset && /^[a-zA-Z0-9_-]+$/.test(preset) ? preset : undefined;
  const promptSearchDirs = getConfigSearchDirs().flatMap((configDir) => {
    const promptsDir = path.join(configDir, PROMPTS_DIR_NAME);
    return presetDirName ? [path.join(promptsDir, presetDirName), promptsDir] : [promptsDir];
  });
  const result = {};
  const readFirstPrompt = (fileName, errorPrefix) => {
    for (const dir of promptSearchDirs) {
      const promptPath = path.join(dir, fileName);
      if (!fs.existsSync(promptPath)) {
        continue;
      }
      try {
        return fs.readFileSync(promptPath, "utf-8");
      } catch (error) {
        console.warn(`[opencode-dux] ${errorPrefix} ${promptPath}:`, error instanceof Error ? error.message : String(error));
      }
    }
    return;
  };
  result.prompt = readFirstPrompt(`${agentName}.md`, "Error reading prompt file");
  result.appendPrompt = readFirstPrompt(`${agentName}_append.md`, "Error reading append prompt file");
  return result;
}
// src/config/utils.ts
function getAgentOverride(config, name) {
  const overrides = config?.agents ?? {};
  return overrides[name] ?? overrides[Object.keys(AGENT_ALIASES).find((k) => AGENT_ALIASES[k] === name) ?? ""];
}
