// src/utils/logger.ts
import * as fs2 from "node:fs";
import { appendFile } from "node:fs/promises";
import * as os from "node:os";
import * as path2 from "node:path";
var LOG_PREFIX = "opencode-dux.";
var LOG_SUFFIX = ".log";
var MAX_LOG_FILES = 10;
var MAX_BG_TASK_FILES = 10;
var logFile = null;
var writeChain = Promise.resolve();
function getLogDir() {
  return process.env.OPENCODE_LOG_DIR ?? path2.join(os.homedir(), ".local/share/opencode");
}
function trimByCount(filePaths, maxFiles, preservePath) {
  if (filePaths.length <= maxFiles)
    return;
  const sortedByMtime = filePaths.map((filePath) => {
    try {
      return { filePath, mtimeMs: fs2.statSync(filePath).mtimeMs };
    } catch {
      return null;
    }
  }).filter((entry) => Boolean(entry)).sort((a, b) => a.mtimeMs - b.mtimeMs);
  const overflow = sortedByMtime.length - maxFiles;
  if (overflow <= 0)
    return;
  const candidates = preservePath ? sortedByMtime.filter((entry) => entry.filePath !== preservePath) : sortedByMtime;
  for (const entry of candidates.slice(0, overflow)) {
    try {
      fs2.unlinkSync(entry.filePath);
    } catch {}
  }
}
function cleanupOldLogs(logDir, preservePath) {
  try {
    const entries = fs2.readdirSync(logDir);
    const logFiles = entries.filter((entry) => entry.startsWith(LOG_PREFIX) && entry.endsWith(LOG_SUFFIX)).map((entry) => path2.join(logDir, entry));
    trimByCount(logFiles, MAX_LOG_FILES, preservePath);
  } catch {}
  try {
    const bgTaskDir = path2.join(logDir, "bg-tasks");
    const taskFiles = fs2.readdirSync(bgTaskDir).filter((entry) => entry.endsWith(".json")).map((entry) => path2.join(bgTaskDir, entry));
    trimByCount(taskFiles, MAX_BG_TASK_FILES);
  } catch {}
}
function initLogger(sessionId) {
  const dir = getLogDir();
  try {
    fs2.mkdirSync(dir, { recursive: true });
  } catch {}
  logFile = path2.join(dir, `${LOG_PREFIX}${sessionId}${LOG_SUFFIX}`);
  try {
    fs2.closeSync(fs2.openSync(logFile, "a"));
  } catch {}
  cleanupOldLogs(dir, logFile);
}
function log(message, data) {
  const target = logFile;
  if (!target)
    return;
  try {
    const timestamp = new Date().toISOString();
    let dataStr = "";
    if (data !== undefined) {
      try {
        dataStr = JSON.stringify(data);
      } catch {
        dataStr = "[unserializable]";
      }
    }
    const logEntry = `[${timestamp}] ${message} ${dataStr}
`;
    writeChain = writeChain.then(() => appendFile(target, logEntry)).catch(() => {});
  } catch {}
}

// src/discovery/local.ts
var NAME_TAG_MAP = {
  playwright: ["browser", "ui", "testing"],
  github: ["github", "git"],
  filesystem: ["filesystem", "files"],
  websearch: ["web", "search"],
  context7: ["docs", "search"],
  grep_app: ["search", "code"],
  ast_grep: ["search", "code"]
};
function deriveTags(name) {
  const lower = name.toLowerCase();
  for (const [key, tags] of Object.entries(NAME_TAG_MAP)) {
    if (lower.includes(key)) {
      return [...tags];
    }
  }
  return [];
}
function deriveRecommendedAgents(_name) {
  return [];
}
function determineSource(location) {
  const normalised = location.replace(/\\/g, "/");
  return normalised.includes("src/skills") ? "bundled" : "user";
}
function withTimeout(promise, ms, label) {
  return Promise.race([
    promise,
    new Promise((_, reject) => setTimeout(() => reject(new Error(`${label} timed out after ${ms}ms`)), ms))
  ]);
}
async function scanMcpStatuses(ctx) {
  const response = await withTimeout(ctx.client.mcp.status(), SDK_DISCOVERY_TIMEOUT_MS, "MCP status scan");
  const data = response.data;
  if (!data) {
    return [];
  }
  return Object.entries(data).map(([name, statusInfo]) => ({
    name,
    status: statusInfo.status,
    description: statusInfo.error,
    tags: deriveTags(name),
    recommendedAgents: deriveRecommendedAgents(name)
  }));
}
async function scanInstanceSkills(ctx) {
  const skillFn = ctx.client.instance.skill;
  if (typeof skillFn !== "function") {
    log("[discovery] ctx.client.instance.skill() is not available, returning empty skills");
    return [];
  }
  const response = await withTimeout(skillFn(), SDK_DISCOVERY_TIMEOUT_MS, "Instance skill scan");
  const items = Array.isArray(response?.data) ? response.data : [];
  return items.map((s) => ({
    name: s.name,
    description: s.description,
    location: s.location,
    tags: deriveTags(s.name),
    recommendedAgents: deriveRecommendedAgents(s.name),
    source: determineSource(s.location)
  }));
}
var CACHE_TTL_MS = 5 * 60 * 1000;
var cache = null;
async function scanLocal(ctx) {
  const start = performance.now();
  let mcps = [];
  let skills = [];
  try {
    mcps = await scanMcpStatuses(ctx);
  } catch (err) {
    log("[discovery] MCP scan failed", String(err));
  }
  try {
    skills = await scanInstanceSkills(ctx);
  } catch (err) {
    log("[discovery] skill scan failed", String(err));
  }
  const scanDurationMs = performance.now() - start;
  return {
    skills,
    mcps,
    scannedAt: Date.now(),
    scanDurationMs
  };
}
async function getLocalDiscovery(ctx, forceRefresh) {
  if (!forceRefresh && cache !== null && Date.now() - cache.timestamp < CACHE_TTL_MS) {
    return cache.result;
  }
  const result = await scanLocal(ctx);
  cache = { result, timestamp: Date.now() };
  return result;
}

// src/cli/skills.ts
function normalizeSkillConfig(raw) {
  if (!raw) {
    return { alwaysLoad: [], wildcard: false, excluded: [] };
  }
  if (Array.isArray(raw)) {
    const alwaysLoad = [];
    const excluded = [];
    let wildcard = false;
    for (const item of raw) {
      if (item === "*") {
        wildcard = true;
      } else if (item.startsWith("!")) {
        excluded.push(item.slice(1));
      } else {
        alwaysLoad.push(item);
      }
    }
    return { alwaysLoad, wildcard, excluded };
  }
  return {
    alwaysLoad: raw["always-load"] ?? raw.mandatory ?? [],
    wildcard: raw.wildcard ?? false,
    excluded: []
  };
}
async function getSkillPermissionsForAgent(_agentName, skillList, ctx) {
  const permissions = {
    "*": "deny"
  };
  if (skillList !== undefined) {
    const normalized = normalizeSkillConfig(skillList);
    permissions["*"] = normalized.wildcard ? "allow" : "deny";
    for (const name of normalized.alwaysLoad) {
      permissions[name] = "allow";
    }
    for (const name of normalized.excluded) {
      permissions[name] = "deny";
    }
    if (normalized.wildcard && ctx) {
      try {
        const local = await getLocalDiscovery(ctx);
        for (const skill of local.skills) {
          permissions[skill.name] = "allow";
        }
      } catch {}
    }
    return permissions;
  }
  return permissions;
}

// src/cli/mcps.ts
async function getMcpPermissionsForAgent(_agentName, mcpList) {
  const permissions = {};
  if (mcpList === undefined) {
    permissions["*"] = "allow";
    return permissions;
  }
  const normalized = normalizeSkillConfig(mcpList);
  permissions["*"] = normalized.wildcard ? "allow" : "deny";
  for (const name of normalized.alwaysLoad) {
    permissions[name] = "allow";
  }
  for (const name of normalized.excluded) {
    permissions[name] = "deny";
  }
  return permissions;
}

// src/agents/overrides.ts
function applyOverrides(agent, override) {
  if (override.model) {
    if (Array.isArray(override.model)) {
      agent._modelArray = override.model.map((m) => typeof m === "string" ? { id: m } : m);
      agent.config.model = undefined;
    } else {
      agent.config.model = override.model;
    }
  }
  if (override.variant)
    agent.config.variant = override.variant;
  if (override.temperature !== undefined)
    agent.config.temperature = override.temperature;
  if (override.options) {
    agent.config.options = {
      ...agent.config.options,
      ...override.options
    };
  }
  if (override.displayName) {
    agent.displayName = override.displayName;
  }
}
async function applyDefaultPermissions(agent, configuredSkills, configuredMcps) {
  const existing = agent.config.permission ?? {};
  const skillPermissions = await getSkillPermissionsForAgent(agent.name, configuredSkills);
  const mcpPermissions = await getMcpPermissionsForAgent(agent.name, configuredMcps);
  const questionPerm = existing.question === "deny" ? "deny" : "allow";
  const taskPerm = agent.name === "orchestrator" ? "deny" : undefined;
  const editPerm = agent.name === "orchestrator" ? "deny" : undefined;
  const writePerm = agent.name === "orchestrator" ? "deny" : undefined;
  agent.config.permission = {
    ...existing,
    question: questionPerm,
    ...taskPerm ? { task: taskPerm } : {},
    ...editPerm ? { edit: editPerm } : {},
    ...writePerm ? { write: writePerm } : {},
    skill: {
      ...typeof existing.skill === "object" ? existing.skill : {},
      ...skillPermissions
    },
    mcp: {
      ...typeof existing.mcp === "object" ? existing.mcp : {},
      ...mcpPermissions
    }
  };
}

