var CACHE_MAX_ENTRIES = 100;
var MCP_CACHE_TTL_MS = 24 * 60 * 60 * 1000;
var CACHE_DIR = path3.join(os2.homedir(), ".config", "opencode");
var CACHE_FILE = path3.join(CACHE_DIR, "discovery-cache.json");
