      task_keywords: z2.array(z2.string()).describe("Keywords characterising the task (used to build search queries)"),
      agent_name: z2.string().describe("The subagent name requesting the discovery"),
      existing_mcp_names: z2.array(z2.string()).optional().describe("MCP server names already installed (to avoid duplicate recommendations). " + "If not provided, auto-detects installed MCPs."),
      max_results: z2.number().min(1).max(20).default(5).describe("Maximum number of recommendations to return")
