      accountName: "",
      snapshot_at: data.snapshot_at ?? "",
      balance: data.balance ?? {
        ...EMPTY_BALANCE
      },
      usage: data.usage ?? {
        ...EMPTY_USAGE
      },
      subscription: data.subscription ?? null,
      fetchedAt: now
