  const output = asNumber(msg.info?.tokens?.output) ?? 0;
  const reasoning = asNumber(msg.info?.tokens?.reasoning) ?? 0;
  const cacheRead = asNumber(msg.info?.tokens?.cache?.read) ?? 0;
