async function computeSessionUsageForReconcile(ctx, sessionID) {
  try {
    const messagesResult = await ctx.client.session.messages({
      path: { id: sessionID }
    });
    const allMessages = Array.isArray(messagesResult.data) ? messagesResult.data : [];
    const assistantMsgs = allMessages.filter((m) => m.info?.role === "assistant");
    let totalInput = 0;
    let totalOutput = 0;
    let totalReasoning = 0;
    let totalCacheRead = 0;
    let totalCacheWrite = 0;
    let contextLimit = 0;
    let contextUsed = 0;
    let contextPct = 0;
    await ensureModelContextLimits(ctx.client).catch(() => {});
    const lastTokenMsg = [...assistantMsgs].reverse().find((m) => readTokenTelemetry(m));
    if (lastTokenMsg) {
      const telemetry = readTokenTelemetry(lastTokenMsg);
      if (telemetry) {
        totalInput = telemetry.input;
        totalOutput = telemetry.output;
        totalReasoning = telemetry.reasoning;
        totalCacheRead = telemetry.cacheRead;
        totalCacheWrite = telemetry.cacheWrite;
        contextLimit = telemetry.contextLimit;
        contextUsed = telemetry.input + telemetry.cacheRead + telemetry.output + telemetry.reasoning;
        contextPct = contextLimit > 0 ? contextUsed / contextLimit * 100 : 0;
      }
    }
    if (contextLimit === 0 && contextUsed > 0) {
      const model = mergedSessionModels(readTuiSnapshot())[sessionID];
      const cachedLimit = model ? _modelContextLimitCache.get(model) : undefined;
      if (cachedLimit && cachedLimit > 0) {
        contextLimit = cachedLimit;
        contextPct = contextUsed / contextLimit * 100;
      }
    }
    if (contextUsed > 0 || totalInput > 0 || totalOutput > 0) {
      return {
        sessionID,
        contextUsed,
        contextLimit,
        contextPct,
        input: totalInput,
        output: totalOutput,
        reasoning: totalReasoning,
        cacheRead: totalCacheRead,
        cacheWrite: totalCacheWrite
      };
    }
    return null;
  } catch {
    return null;
  }
}
